-- Teachers

-- Subjects

-- Weekly subject requirements and teacher assignments

-- Verify totals (every active class must equal 40 periods)
select c.name as class, coalesce(sum(cs.weekly_periods),0) as configured_periods, case when coalesce(sum(cs.weekly_periods),0)=40 then 'OK' else 'INVALID' end as status from classes c left join class_subjects cs on cs.class_id=c.id where c.school_id='00000000-0000-4000-8000-000000000001' group by c.id,c.name order by c.id;
select t.name as teacher, count(ta.id) as assignment_count from teachers t left join teacher_assignments ta on ta.teacher_id=t.id where t.school_id='00000000-0000-4000-8000-000000000001' group by t.id,t.name order by t.id;
